      await tester.pumpWidget(
        _wrap(
          PinKeypad(
            enabled: false,
            onSubmit: (_) => fail('should not submit while disabled'),
          ),
        ),
      );

      for (final digit in '1234'.split('')) {
        await _tapDigit(tester, digit);
      }
      await tester.pump(const Duration(milliseconds: 350));

