      await tester.pumpWidget(
        _wrap(PinKeypad(enabled: false, onSubmit: (_) {})),
      );

      await tester.tap(find.byIcon(Icons.backspace_outlined));
      await tester.pump();

      expect(tester.takeException(), isNull);
    },
  );

